    /// The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and managed in Amazon Web Services Se- crets Manager. This setting is valid only if the master user password is managed by RDS in Amazon Web Services Secrets Manager for the DB cluster. The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key. To use a KMS key in a dif- ferent Amazon Web Services account, specify the key ARN or alias ARN. If you don't specify MasterUserSecretKmsKeyId , then the aws/se- cretsmanager KMS key is used to encrypt the secret. If the secret is in a different Amazon Web Services account, then you can't use the aws/secretsmanager KMS key to encrypt the secret, and you must use a customer managed KMS key. There is a default KMS key for your Amazon Web Services account. Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region. Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters
    /// </summary>
    [SecretValue]
    [CliOption("--master-user-secret-kms-key-id")]
    public string? MasterUserSecretKmsKeyId { get; set; }

    /// <summary>
    /// The CA certificate identifier to use for the DB cluster's server certificate. For more information, see Using SSL/TLS to encrypt a connection to a DB instance in the Amazon RDS User Guide . Valid for Cluster Type: Multi-AZ DB clusters
    /// </summary>
    [CliOption("--ca-certificate-identifier")]
    public string? CaCertificateIdentifier { get; set; }

    /// <summary>
    /// The lifecycle type for this DB cluster. NOTE: By default, this value is set to open-source-rds-extended-sup- port , which enrolls your DB cluster into Amazon RDS Extended Support. At the end of standard support, you can avoid charges for Extended Support by setting the value to open-source-rds-ex- tended-support-disabled . In this case, creating the DB cluster will fail if the DB major version is past its end of standard support date. You can use this setting to enroll your DB cluster into Amazon RDS Extended Support. With RDS Extended Support, you can run the se- lected major engine version on your DB cluster past the end of stan- dard support for that engine version. For more information, see the following sections: o Amazon Aurora - Amazon RDS Extended Support with Amazon Aurora in the Amazon Aurora User Guide o Amazon RDS - Amazon RDS Extended Support with Amazon RDS in the Amazon RDS User Guide Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters Valid Values: open-source-rds-extended-support | open-source-rds-ex- tended-support-disabled Default: open-source-rds-extended-support
    /// </summary>
    [CliOption("--engine-lifecycle-support")]
    public string? EngineLifecycleSupport { get; set; }

    /// <summary>
    /// Tags to assign to resources associated with the DB cluster. Valid Values: o cluster-auto-backup - The DB cluster's automated backup. (structure) The tags to apply to resources when creating or modifying a DB instance or DB cluster. When you specify a tag, you must specify the resource type to tag, otherwise the request will fail. ResourceType -&gt; (string) The type of resource to tag on creation. Valid Values: o auto-backup - The DB instance's automated backup. o cluster-auto-backup - The DB cluster's automated backup. Tags -&gt; (list) A list of tags. For more information, see Tagging Amazon RDS resources in the Amazon RDS User Guide or Tagging Amazon Aurora and Amazon RDS resources in the Amazon Aurora User Guide . (structure) Metadata assigned to an Amazon RDS resource consisting of a key-value pair. For more information, see Tagging Amazon RDS resources in the Amazon RDS User Guide or Tagging Amazon Aurora and Amazon RDS resources in the Amazon Aurora User Guide . Key -&gt; (string) A key is the required name of the tag. The string value can be from 1 to 128 Unicode characters in length and can't be prefixed with aws: or rds: . The string can only contain only the set of Unicode let- ters, digits, white-space, '_', '.', ':', '/', '=', '+', '-', '@' (Java regex: "^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$"). Value -&gt; (string) A value is the optional value of the tag. The string value can be from 1 to 256 Unicode characters in length and can't be prefixed with aws: or rds: . The string can only contain only the set of Unicode let- ters, digits, white-space, '_', '.', ':', '/', '=', '+', '-', '@' (Java regex: "^([\p{L}\p{Z}\p{N}_.:/=+\-@]*)$"). Shorthand Syntax: ResourceType=string,Tags=[{Key=string,Value=string},{Key=string,Value=string}] ... JSON Syntax: [ { "ResourceType": "string", "Tags": [ { "Key": "string", "Value": "string" } ... ] } ... ]
    /// </summary>
    [CliOption("--tag-specifications")]
    public IEnumerable<string>? TagSpecifications { get; set; }

    /// <summary>
    /// Specifies the authentication type for the master user. With IAM mas- ter user authentication, you can configure the master DB user with IAM database authentication when you create a DB cluster. You can specify one of the following values: o password - Use standard database authentication with a password. o iam-db-auth - Use IAM database authentication for the master user. Valid for Cluster Type: Aurora DB clusters and Multi-AZ DB clusters This option is only valid for RDS for PostgreSQL and Aurora Post- greSQL engines. Possible values: o password o iam-db-auth
    /// </summary>
    [CliOption("--master-user-authentication-type")]
    public AwsRdsCreateDbClusterMasterUserAuthenticationType? MasterUserAuthenticationType { get; set; }

    [CliFlag("--with-express-configuration")]
    public bool? WithExpressConfiguration { get; set; }

    /// <summary>
    /// A list of Amazon Web Services Identity and Access Management (IAM) roles to associate with the DB cluster. Each role grants the DB cluster permission to access other Amazon Web Services on your be- half. For each role, specify a role ARN and, optionally, the feature name (such as s3Import , s3Export , or Lambda ). Valid for Cluster Type: Aurora DB clusters only Constraints: o min: 0 o max: 15 (structure) Contains information about an Amazon Web Services Identity and Access Management (IAM) role to associate with a DB cluster. You can specify this structure in the AssociatedRoles parameter of CreateDBCluster , RestoreDBClusterFromS3 , RestoreDBCluster- FromSnapshot , and RestoreDBClusterToPointInTime . RoleArn -&gt; (string) [required] The Amazon Resource Name (ARN) of the IAM role to associate with the DB cluster. Constraints: o min: 20 o max: 2048 o pattern: arn:aws[a-z-]*:iam::[0-9]*:role/.* FeatureName -&gt; (string) The name of the feature associated with the IAM role. For in- formation about supported feature names, see DBEngineVersion . Shorthand Syntax: RoleArn=string,FeatureName=string ... JSON Syntax: [ { "RoleArn": "string", "FeatureName": "string" } ... ]
    /// </summary>
    [CliOption("--associated-roles")]
    public IEnumerable<string>? AssociatedRoles { get; set; }

    /// <summary>
    /// The ID of the region that contains the source for the db cluster.
    /// </summary>
    [CliOption("--source-region")]
    public string? SourceRegion { get; set; }

    [CliOption("--cli-input-json")]
    public string? CliInputJson { get; set; }

    [CliOption("--generate-cli-skeleton")]
    public string? GenerateCliSkeleton { get; set; }

}
